const liveTrend = '';
const statusField = (options: string[]): FieldConfig => ({ key: 'status', label: 'Status', type: 'select', options, required: true });
const ownerField = (label = 'Owner'): FieldConfig => ({ key: 'ownerName', label, required: true, placeholder: `Enter ${label.toLowerCase()} name` });
const kpi = (label: string, icon: string): KpiConfig => ({ label, value: '0', trend: liveTrend, icon });

function config(input: Omit<ModuleConfig, 'rows' | 'donutData' | 'barData'> & { columns: ColumnConfig[]; fields: FieldConfig[] }): ModuleConfig {
  return { ...input, rows: [], donutData: [], barData: [] };
}

